  Future<void> generate() async { if (title.text.trim().isEmpty || description.text.trim().isEmpty || candidates.any((c) => c.text.trim().isEmpty)) { setState(() {}); return; } final poll = await widget.service.createPoll(title: title.text.trim(), description: description.text.trim(), minutes: minutes, names: candidates.map((c) => c.text.trim()).toList()); if (mounted) setState(() => created = poll); }
