      ListTile(leading: const Icon(Icons.send, color: Colors.blue), title: const Text('Telegram'), onTap: () { Navigator.pop(sheetContext); launchUrl(Uri.parse('https://t.me/share/url?url=${Uri.encodeComponent(link)}&text=${Uri.encodeComponent('Join my VoteSphere poll')}'), mode: LaunchMode.externalApplication); }),
